# Writes the hedra command file of every Swarm Ward model except the hero, and the ground's texture:
#   ground.txt + ground.png   the moor plane that rides with the camera, the lantern's pool in its texture
#   decor0..3.txt             four 12 x 12 m patches of moor that leapfrog round the hero
#   moths.txt                 a swarm of five murk moths (one bone)
#   shambler.txt, hound.txt   the common foes
#   brute.txt, boss.txt       the elite (a cairn brute) and the dawn boss (the Mire King)
#   mote.txt, ring.txt, spark.txt, ember.txt   the weapons
#   wisp.txt, flask.txt       the pickups
# Run from models/env: /usr/bin/python3 make_models.py
# hedra: up Z, front -Y (towards the camera); glTF world = (x, z, -y). Colours exact Rosy 42.
import math, os, random
from PIL import Image

HERE = os.path.dirname(os.path.abspath(__file__))

def srgb(h):
    h = h.lstrip("#")
    return " ".join(f"{int(h[i:i + 2], 16) / 255:.4f}" for i in (0, 2, 4))

def mat(name, hexc, emit=False):
    s = f"material new {name} --base-color {srgb(hexc)} --no-slot"
    return s + (f" --emission {srgb(hexc)}" if emit else "")

def rot_to(a, b):
    d = [b[i] - a[i] for i in range(3)]
    n = math.sqrt(sum(v * v for v in d))
    dx, dy, dz = (v / n for v in d)
    return n, -math.degrees(math.asin(dy)), math.degrees(math.atan2(dx, dz))

def bar(name, a, b, r, verts=6, m=None):
    n, rx, ry = rot_to(a, b)
    c = [(a[i] + b[i]) / 2 for i in range(3)]
    L = [f"add mesh cylinder --name {name} --vertices {verts} --radius {r} --depth {n + r * 0.5:.4f} "
         f"--location {c[0]:.4f} {c[1]:.4f} {c[2]:.4f} --rotation {rx:.2f} {ry:.2f} 0", "apply --rotation"]
    return L + ([f"material assign {m}"] if m else [])

def cone_to(name, a, b, r, verts=5, m=None):
    """a cone with its base at a and its tip at b"""
    n, rx, ry = rot_to(a, b)
    c = [(a[i] + b[i]) / 2 for i in range(3)]
    L = [f"add mesh cone --name {name} --vertices {verts} --radius1 {r} --radius2 0 --depth {n:.4f} "
         f"--location {c[0]:.4f} {c[1]:.4f} {c[2]:.4f} --rotation {rx:.2f} {ry:.2f} 0", "apply --rotation"]
    return L + ([f"material assign {m}"] if m else [])

def box(name, sx, sy, sz, x, y, z, m=None, rot=None):
    L = [f"add mesh cube --name {name} --size 1 --location {x:.4f} {y:.4f} {z:.4f}", f"scale {sx} {sy} {sz}", "apply --scale"]
    if rot:
        L += [f"set rotation {rot[0]} {rot[1]} {rot[2]}", "apply --rotation"]
    return L + ([f"material assign {m}"] if m else [])

def ico(name, r, x, y, z, s=(1, 1, 1), m=None, rnd=0.0, seed=1, cut=None, sub=1):
    L = [f"add mesh ico-sphere --name {name} --subdivisions {sub} --radius {r} --location {x:.4f} {y:.4f} {z:.4f}",
         f"scale {s[0]} {s[1]} {s[2]}", "apply --scale"]
    if m:
        L.append(f"material assign {m}")
    if rnd or cut is not None:
        L += ["apply --location", "mode edit", "select all"]
        if rnd:
            L.append(f"randomize --amount {rnd:.3f} --seed {seed}")
        if cut is not None:   # drop the faces buried under the ground (world z below `cut`)
            L += [f'select face where "pos.z < {cut}"', "delete only-faces"]
        L.append("mode object")
    return L

def octa(name, r, h, x, y, z, m):
    """an octahedron: two 4-sided cones base to base (r across, h tall)"""
    return [f"add mesh cone --name {name} --vertices 4 --radius1 {r} --radius2 0 --depth {h / 2:.4f} --location {x} {y} {z + h / 4:.4f}",
            f"add mesh cone --name {name}B --vertices 4 --radius1 {r} --radius2 0 --depth {h / 2:.4f} --location {x} {y} {z - h / 4:.4f} --rotation 180 0 0",
            "apply --rotation", f"select {name} {name}B", f"active {name}", "join", f"material assign {m}"]

def write(name, lines, header):
    body = [f"# {l}" for l in header] + ["# Generated by make_models.py. Up Z, front -Y.", "new"] + lines
    open(os.path.join(HERE, name + ".txt"), "w").write("\n".join(body) + "\n")

def finish(objs, keep, out):
    return ["select " + " ".join(objs), f"active {keep}", "join", "select all", "shade flat", f"export {out}.glb"]

BAY = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5]

# ---------------------------------------------------------------- ground + its texture (the light pool)
# 12 x 10 m at 0.1 m a texel (120 x 100): the moor (#283540) with the lantern's pool in the middle,
# two lit steps of the moor's own ramp thinning out through a 4 x 4 Bayer threshold: #2f5753 to
# 2.7 m, #3b7d4f to 1.6 m. The ground rides with the camera, which is locked on the hero, so the
# pool stays under him.
GW, GH, TX = 12.0, 10.0, 0.1
W, H = int(GW / TX), int(GH / TX)
im = Image.new("RGB", (W, H))
for y in range(H):
    for x in range(W):
        d = math.hypot((x + 0.5) * TX - GW / 2, (y + 0.5) * TX - GH / 2)
        t = (BAY[(x % 4) + (y % 4) * 4] + 0.5) / 16
        k1 = max(0.0, min(1.0, (2.7 - d) / 1.1))
        k2 = max(0.0, min(1.0, (1.6 - d) / 0.9))
        c = (0x28, 0x35, 0x40)
        if t < k1:
            c = (0x2f, 0x57, 0x53)
        if t < k2:
            c = (0x3b, 0x7d, 0x4f)
        im.putpixel((x, y), c)
im.save(os.path.join(HERE, "ground.png"))
write("ground", [mat("Ground", "#ffffff"), "material texture Ground base-color ground.png",
                 f"add mesh plane --name Ground --size 1", f"scale {GW} {GH} 1", "apply --scale",
                 "material assign Ground", "mode edit", "select all", "uv project-from-view top --scale-to-bounds",
                 "mode object", "export ground.glb"],
      ["The moor under the hero: a 12 x 10 m plane, its texture (ground.png) the moor with the lantern's",
       "pool of light. It rides with the camera (one bone), so it must stay uniform outside the pool."])

# ---------------------------------------------------------------- decor patches
P = 12.0  # the patch, and the leapfrog grid's cell
def heather(i, x, y, r, rnd):
    n = f"H{i}"
    return ico(n, r, x, y, 0, (rnd.uniform(0.9, 1.25), rnd.uniform(0.85, 1.15), rnd.uniform(0.42, 0.6)), "Heather",
               r * 0.12, i + 3, 0.02) + ["mode edit", 'select face where "normal.z > 0.75"', "material assign Bloom",
                                         "mode object"], n

def tuft(i, x, y, rnd):
    names, L = [], []
    for k in range(3):
        a = rnd.uniform(0, 2 * math.pi)
        h = rnd.uniform(0.22, 0.34)
        tip = (x + math.cos(a) * 0.09, y + math.sin(a) * 0.09, h)
        n = f"T{i}_{k}"
        L += cone_to(n, (x + math.cos(a) * 0.03, y + math.sin(a) * 0.03, 0), tip, 0.065, 4, "Grass")
        names.append(n)
    return L, names

def pebble(i, x, y, r, rnd):
    n = f"P{i}"
    return ico(n, r, x, y, 0, (rnd.uniform(0.9, 1.4), 1, rnd.uniform(0.5, 0.75)), "Stone", r * 0.15, i + 50, 0.01), n

def mound(i, x, y, r, rnd):
    n = f"M{i}"
    return ico(n, r, x, y, -0.02, (rnd.uniform(1.0, 1.5), rnd.uniform(0.8, 1.1), 0.22), "Turf", r * 0.08, i + 90, 0.03), n

def standing(name, x, y, h, w, tilt, yaw, rnd):
    return box(name, w, w * 0.65, h, x, y, h / 2, "Stone", (tilt, rnd.uniform(-4, 4), yaw)) + \
        ["apply --location", "mode edit", "select all", f"randomize --amount 0.03 --seed {int(h * 100)}",
         'select face where "normal.z < -0.9"', "delete only-faces", 'select face where "normal.z > 0.8"',
         "material assign Lichen", "mode object"]

def ward_post(x, y):
    """an old ward post: a lamp post the lamplighter tends, its lamp dark"""
    L = bar("WPost", (x, y, 0), (x, y, 1.45), 0.05, 6, "Wood")
    L += bar("WArm", (x, y, 1.38), (x - 0.3, y, 1.38), 0.035, 6, "Wood")
    L += box("WLamp", 0.18, 0.18, 0.2, x - 0.3, y, 1.2, "Iron")
    L += [f"add mesh cone --name WCap --vertices 4 --radius1 0.15 --radius2 0.02 --depth 0.09 --location {x - 0.3} {y} 1.345 --rotation 0 0 45",
          "apply --rotation", "material assign Iron"]
    L += box("WGlass", 0.2, 0.12, 0.13, x - 0.3, y, 1.2, "DarkGlass")
    L += box("WGlass2", 0.12, 0.2, 0.13, x - 0.3, y, 1.2, "DarkGlass")
    return L, ["WPost", "WArm", "WLamp", "WCap", "WGlass", "WGlass2"]

DECOR_MATS = [mat("Heather", "#692464"), mat("Bloom", "#9c2a70"), mat("Grass", "#3b7d4f"), mat("Stone", "#686f99"),
              mat("Lichen", "#a3a7c2"), mat("Turf", "#2f5753"), mat("Wood", "#52333f"), mat("Iron", "#3b2027"),
              mat("DarkGlass", "#3a3f5e"), mat("Water", "#3a3f5e"), mat("Reed", "#63ab3f"), mat("Stem", "#dfe0e8"),
              mat("Cap", "#92e8c0", True), mat("Bark", "#3d2936")]

def decor(idx, seed, landmark):
    rnd = random.Random(seed)
    L = list(DECOR_MATS)
    objs = []
    taken = []   # (x, y, r): keep things from piling up
    def spot(r, margin=0.4):
        for _ in range(200):
            x, y = rnd.uniform(-P / 2 + margin, P / 2 - margin), rnd.uniform(-P / 2 + margin, P / 2 - margin)
            if all(math.hypot(x - a, y - b) > r + c for a, b, c in taken):
                taken.append((x, y, r))
                return x, y
        return None
    lm, lm_objs, lm_r = landmark(rnd)
    taken.append((lm_r[0], lm_r[1], lm_r[2]))
    L += lm
    objs += lm_objs
    for i in range(9):
        s = spot(0.9)
        if s:
            c, n = mound(i, s[0], s[1], rnd.uniform(0.5, 0.8), rnd); L += c; objs.append(n)
    for i in range(20):
        s = spot(0.42)
        if s:
            c, n = heather(i, s[0], s[1], rnd.uniform(0.22, 0.36), rnd); L += c; objs.append(n)
    for i in range(26):
        s = spot(0.18)
        if s:
            c, ns = tuft(i, s[0], s[1], rnd); L += c; objs += ns
    for i in range(14):
        s = spot(0.15)
        if s:
            c, n = pebble(i, s[0], s[1], rnd.uniform(0.11, 0.17), rnd); L += c; objs.append(n)
    L += finish(objs, objs[0], f"decor{idx}")
    return L

def lm_stones(rnd):
    L = standing("SA", -0.4, 0.2, 1.5, 0.5, 6, 20, rnd) + standing("SB", 0.55, -0.15, 1.1, 0.42, -8, -15, rnd)
    L += standing("SC", 0.1, 0.75, 0.35, 0.7, 70, 40, rnd)    # a fallen one
    return L, ["SA", "SB", "SC"], (0.0, 0.2, 1.3)

def lm_tree(rnd):
    L = bar("Trunk", (0, 0, -0.05), (0.15, 0.1, 1.1), 0.11, 6, "Bark")
    names = ["Trunk"]
    for k, (a, b) in enumerate([((0.15, 0.1, 1.05), (0.65, 0.2, 1.55)), ((0.12, 0.08, 0.9), (-0.45, -0.1, 1.4)),
                                ((0.15, 0.1, 1.1), (0.2, -0.3, 1.75)), ((0.55, 0.18, 1.45), (0.85, -0.05, 1.7)),
                                ((-0.3, -0.06, 1.25), (-0.55, 0.2, 1.6))]):
        L += bar(f"Br{k}", a, b, 0.055 if k < 3 else 0.045, 5, "Bark")
        names.append(f"Br{k}")
    w, wn = ward_post(1.3, 0.5)
    return L + w, names + wn, (0.4, 0.2, 1.4)

def lm_pool(rnd):
    L = ["add mesh circle --name Pool --vertices 12 --radius 1 --cap-fill ngon --location 0 0 0.09",
         "scale 1.0 0.6 1", "apply --scale", "material assign Water"]
    names = ["Pool"]
    for k in range(11):
        a = k / 11 * 2 * math.pi + rnd.uniform(-0.15, 0.15)
        L += ico(f"R{k}", rnd.uniform(0.13, 0.19), math.cos(a) * 1.05, math.sin(a) * 0.66, 0,
                 (1.2, 1, 0.6), "Stone", 0.015, k + 200, 0.01)
        names.append(f"R{k}")
    for k in range(5):
        x, y = rnd.uniform(-0.8, 0.8), rnd.uniform(-0.3, 0.3)
        if abs(y) < 0.25 and abs(x) < 0.6:
            y = 0.45 if y > 0 else -0.45
        h = rnd.uniform(0.45, 0.7)
        L += bar(f"Reed{k}", (x, y, 0.05), (x + rnd.uniform(-0.06, 0.06), y, h), 0.035, 4, "Reed")
        names.append(f"Reed{k}")
    return L, names, (0.0, 0.0, 1.4)

def lm_ring(rnd):
    L, names = [], []
    for k in range(9):
        a = k / 9 * 2 * math.pi
        x, y = math.cos(a) * 0.85, math.sin(a) * 0.85
        h = rnd.uniform(0.1, 0.16)
        L += bar(f"St{k}", (x, y, 0), (x, y, h), 0.05, 5, "Stem")
        L += [f"add mesh cone --name Cp{k} --vertices 6 --radius1 0.1 --radius2 0.03 --depth 0.07 --location {x:.3f} {y:.3f} {h + 0.03:.3f}",
              "material assign Cap"]
        names += [f"St{k}", f"Cp{k}"]
    w, wn = ward_post(1.6, -0.4)
    c = ico("Cairn", 0.3, -1.4, 0.6, 0, (1, 1, 0.8), "Stone", 0.04, 300, 0.01)
    c2 = ico("Cairn2", 0.2, -1.42, 0.6, 0.3, (1, 1, 0.8), "Stone", 0.03, 301, None)
    return L + w + c + c2, names + wn + ["Cairn", "Cairn2"], (0.0, 0.0, 1.9)

for i, (seed, lm) in enumerate([(11, lm_stones), (22, lm_tree), (33, lm_pool), (44, lm_ring)]):
    write(f"decor{i}", decor(i, seed, lm),
          [f"Moor patch {i}: 12 x 12 m of heather clumps (blooms on their tops), grass tufts, turf mounds and",
           "pebbles round one landmark. Four patches leapfrog on a 12 m grid round the hero (game.as)."])

# ---------------------------------------------------------------- moths: a swarm of five (one bone)
MOTHS = [(0.0, 0.0, 0.78, 0), (-0.34, 0.16, 0.6, 18), (0.32, 0.24, 0.7, -22), (-0.16, -0.32, 0.55, -10), (0.26, -0.26, 0.9, 25)]
L = [mat("Wing", "#a3a7c2"), mat("Body", "#686f99"), mat("Eye", "#ff5277", True)]
objs = []
for k, (x, y, z, yaw) in enumerate(MOTHS):
    parts = [f"B{k}", f"WL{k}", f"WR{k}", f"E{k}"]
    L += [f"add mesh ico-sphere --name B{k} --subdivisions 1 --radius 0.05 --location 0 0 0", "scale 1 2.2 1",
          "apply --scale", "material assign Body"]
    for side, nm in ((-1, "WL"), (1, "WR")):
        L += [f"add mesh plane --name {nm}{k} --size 1 --location {side * 0.1} 0.02 0.0", "scale 0.17 0.15 1",
              "apply --scale", f"set rotation 0 {side * -22} {side * -8}", "apply --rotation", "material assign Wing"]
    L += box(f"E{k}", 0.075, 0.035, 0.035, 0, -0.105, 0.01, "Eye")
    L += ["select " + " ".join(parts), f"active B{k}", "join", f"set rotation 0 0 {yaw}", "apply --rotation",
          f"set location {x} {y} {z}", "apply --location"]
    objs.append(f"B{k}")
L += finish(objs, "B0", "moths")
write("moths", L, ["A swarm of five murk moths: a body, two flat wings (two-sided) raised in a shallow V and a",
                   "pair of glowing eyes each, at 0.55-0.9 m over the ground round the swarm's centre. One bone."])

# ---------------------------------------------------------------- peat shambler
L = [mat("Peat", "#8f4d57"), mat("Moss", "#63ab3f"), mat("Twig", "#3d2936"), mat("Eye", "#ff5277", True)]
L += ico("Body", 0.42, 0, 0.02, 0.4, (1.0, 0.9, 1.12), "Peat", 0.05, 5, 0.12)
L += ["mode edit", 'select face where "normal.z > 0.6"', "material assign Moss", "mode object"]
L += ico("Head", 0.21, 0, -0.17, 0.8, (1.1, 1, 0.9), "Peat", 0.025, 6)
L += ["mode edit", 'select face where "normal.z > 0.6"', "material assign Moss", "mode object"]
L += bar("ArmL", (0.34, -0.05, 0.6), (0.44, -0.24, 0.22), 0.09, 6, "Peat")
L += bar("ArmR", (-0.34, -0.05, 0.6), (-0.42, -0.26, 0.26), 0.09, 6, "Peat")
L += cone_to("TwigA", (0.08, -0.12, 0.92), (0.2, -0.05, 1.22), 0.04, 4, "Twig")
L += cone_to("TwigB", (-0.1, -0.1, 0.92), (-0.25, 0.0, 1.16), 0.04, 4, "Twig")
L += box("EyeL", 0.07, 0.04, 0.06, 0.085, -0.37, 0.82, "Eye") + box("EyeR", 0.07, 0.04, 0.06, -0.085, -0.37, 0.82, "Eye")
L += finish(["Body", "Head", "ArmL", "ArmR", "TwigA", "TwigB", "EyeL", "EyeR"], "Body", "shambler")
write("shambler", L, ["A peat shambler: a lumpy peat mound (moss on its top faces) with a head, two dragging arms,",
                      "two twigs and glowing eyes; 0.9 x 0.8 x 1.15 m."])

# ---------------------------------------------------------------- barrow hound
L = [mat("Hide", "#692464"), mat("Skull", "#a3a7c2"), mat("Eye", "#ff5277", True)]
L += box("Body", 0.3, 0.62, 0.24, 0, 0.08, 0.42, "Hide", (-6, 0, 0))
L += box("Chest", 0.34, 0.26, 0.32, 0, -0.2, 0.46, "Hide")
L += box("Head", 0.25, 0.26, 0.22, 0, -0.42, 0.6, "Skull", (8, 0, 0))
L += box("Snout", 0.16, 0.2, 0.12, 0, -0.6, 0.55, "Skull")
L += cone_to("EarL", (0.08, -0.38, 0.68), (0.13, -0.32, 0.86), 0.06, 4, "Hide")
L += cone_to("EarR", (-0.08, -0.38, 0.68), (-0.13, -0.32, 0.86), 0.06, 4, "Hide")
for nm, x, y in (("LegFL", 0.1, -0.22), ("LegFR", -0.1, -0.22), ("LegBL", 0.1, 0.3), ("LegBR", -0.1, 0.3)):
    L += bar(nm, (x, y, 0.36), (x, y - 0.03, 0.0), 0.05, 5, "Hide")
L += bar("Tail", (0, 0.36, 0.48), (0, 0.6, 0.64), 0.04, 5, "Hide")
L += box("EyeL", 0.06, 0.04, 0.05, 0.07, -0.555, 0.64, "Eye") + box("EyeR", 0.06, 0.04, 0.05, -0.07, -0.555, 0.64, "Eye")
L += finish(["Body", "Chest", "Head", "Snout", "EarL", "EarR", "LegFL", "LegFR", "LegBL", "LegBR", "Tail", "EyeL", "EyeR"],
            "Body", "hound")
write("hound", L, ["A barrow hound: a lean purple dog with a pale skull mask, pointed ears, glowing eyes; 0.36 x 0.95 x 0.86 m."])

# ---------------------------------------------------------------- cairn brute (elite)
L = [mat("Rock", "#686f99"), mat("Moss", "#3b7d4f"), mat("Rune", "#92e8c0", True)]
L += box("LegL", 0.32, 0.32, 0.5, 0.27, 0.02, 0.24, "Rock", (0, 0, 8)) + box("LegR", 0.32, 0.32, 0.5, -0.27, 0.02, 0.24, "Rock", (0, 0, -8))
L += ico("Torso", 0.56, 0, 0.0, 0.98, (1.12, 0.8, 0.95), "Rock", 0.05, 7)
L += ["mode edit", 'select face where "normal.z > 0.55"', "material assign Moss", "mode object"]
L += ico("Head", 0.22, 0, -0.1, 1.6, (1.2, 1, 0.9), "Rock", 0.02, 8)
L += ico("ShoulderL", 0.27, 0.68, 0.0, 1.22, (1, 1, 0.9), "Rock", 0.03, 9) + ico("ShoulderR", 0.27, -0.68, 0.0, 1.22, (1, 1, 0.9), "Rock", 0.03, 10)
L += ico("ArmL", 0.2, 0.78, -0.05, 0.86, (1, 1, 1.2), "Rock", 0.02, 11) + ico("ArmR", 0.2, -0.78, -0.05, 0.86, (1, 1, 1.2), "Rock", 0.02, 12)
L += ico("FistL", 0.27, 0.8, -0.14, 0.48, (1, 1, 0.9), "Rock", 0.03, 13) + ico("FistR", 0.27, -0.8, -0.14, 0.48, (1, 1, 0.9), "Rock", 0.03, 14)
L += box("RuneA", 0.08, 0.04, 0.2, -0.16, -0.44, 1.02, "Rune") + box("RuneB", 0.2, 0.04, 0.07, 0.12, -0.44, 1.1, "Rune")
L += box("RuneC", 0.07, 0.04, 0.16, 0.14, -0.43, 0.84, "Rune")
L += box("EyeL", 0.08, 0.04, 0.05, 0.09, -0.29, 1.62, "Rune") + box("EyeR", 0.08, 0.04, 0.05, -0.09, -0.29, 1.62, "Rune")
L += finish(["LegL", "LegR", "Torso", "Head", "ShoulderL", "ShoulderR", "ArmL", "ArmR", "FistL", "FistR", "RuneA", "RuneB",
             "RuneC", "EyeL", "EyeR"], "Torso", "brute")
write("brute", L, ["A cairn brute: stacked moor stones (moss on top), boulder fists, glowing runes and eyes; 1.6 x 0.9 x 1.8 m."])

# ---------------------------------------------------------------- the Mire King (boss)
L = [mat("Peat", "#8f4d57"), mat("Moss", "#63ab3f"), mat("Antler", "#dfe0e8"), mat("Eye", "#ff5277", True)]
L += bar("LegL", (0.42, 0.05, 0.75), (0.48, 0.0, 0.0), 0.22, 6, "Peat") + bar("LegR", (-0.42, 0.05, 0.75), (-0.48, 0.0, 0.0), 0.22, 6, "Peat")
L += ico("Body", 0.95, 0, 0.05, 1.35, (1.15, 0.85, 1.0), "Peat", 0.09, 21, None, 1)
L += ["mode edit", 'select face where "normal.z > 0.5"', "material assign Moss", "mode object"]
L += ico("Head", 0.42, 0, -0.5, 2.15, (1.1, 1, 0.9), "Peat", 0.04, 22)
L += ["mode edit", 'select face where "normal.z > 0.6"', "material assign Moss", "mode object"]
L += bar("ArmL", (0.95, -0.15, 1.75), (1.25, -0.45, 0.45), 0.2, 6, "Peat") + bar("ArmR", (-0.95, -0.15, 1.75), (-1.25, -0.45, 0.45), 0.2, 6, "Peat")
L += ico("HandL", 0.3, 1.27, -0.5, 0.32, (1, 1, 0.8), "Peat", 0.03, 23) + ico("HandR", 0.3, -1.27, -0.5, 0.32, (1, 1, 0.8), "Peat", 0.03, 24)
names = ["LegL", "LegR", "Body", "Head", "ArmL", "ArmR", "HandL", "HandR"]
for s, nm in ((1, "L"), (-1, "R")):     # the crown: two antlers, each a beam and three tines
    beam = [(s * 0.2, -0.5, 2.45), (s * 0.55, -0.4, 2.85), (s * 0.75, -0.3, 3.25)]
    L += bar(f"Ant{nm}0", beam[0], beam[1], 0.075, 5, "Antler") + bar(f"Ant{nm}1", beam[1], beam[2], 0.06, 5, "Antler")
    L += cone_to(f"Tin{nm}0", beam[1], (s * 0.42, -0.62, 3.2), 0.055, 4, "Antler")
    L += cone_to(f"Tin{nm}1", beam[2], (s * 0.62, -0.42, 3.55), 0.05, 4, "Antler")
    L += cone_to(f"Tin{nm}2", beam[1], (s * 0.95, -0.35, 2.95), 0.05, 4, "Antler")
    names += [f"Ant{nm}0", f"Ant{nm}1", f"Tin{nm}0", f"Tin{nm}1", f"Tin{nm}2"]
L += box("EyeL", 0.13, 0.05, 0.1, 0.17, -0.9, 2.2, "Eye") + box("EyeR", 0.13, 0.05, 0.1, -0.17, -0.9, 2.2, "Eye")
L += box("Maw", 0.34, 0.05, 0.08, 0, -0.9, 1.98, "Eye")
L += finish(names + ["EyeL", "EyeR", "Maw"], "Body", "boss")
write("boss", L, ["The Mire King: a hunched peat giant (moss on its back), long arms to the ground, a crown of pale",
                  "antlers, glowing eyes and maw; 2.8 x 1.5 x 3.5 m."])

# ---------------------------------------------------------------- weapons and pickups
write("mote", [mat("Light", "#ffee83", True)] + octa("Mote", 0.12, 0.26, 0, 0, 0, "Light") + ["export mote.glb"],
      ["A ward mote: an octahedron of lantern light, 0.24 x 0.26 m, centred on its origin (unlit)."])
write("ring", [mat("Light", "#ffee83", True),
               "add mesh torus --name Ring --major-segments 72 --minor-segments 4 --major-radius 3.0 --minor-radius 0.09 --location 0 0 0",
               "scale 1 1 0.7", "apply --scale", "material assign Light", "mode edit", 'select face where "normal.z < -0.2"',
               "delete only-faces", "mode object", "export ring.glb"],
      ["The lamp pulse: a ring of light 3 m in radius (its largest; the game scales it down), its",
       "underside removed (unlit)."])
write("spark", [mat("Spark", "#ff8933", True), mat("Core", "#ffae70", True),
                "add mesh ico-sphere --name Spark --subdivisions 1 --radius 0.07 --location 0 0 0", "scale 1 2.6 1",
                "apply --scale", "material assign Spark", "mode edit", 'select face where "pos.y < -0.08"',
                "material assign Core", "mode object", "export spark.glb"],
      ["A flint spark: a stretched icosahedron 0.14 x 0.36 m pointing -Y (its flight), a hot tip (unlit)."])
L = [mat("Coal", "#e64539", True), mat("Flame", "#ff8933", True), mat("Tip", "#ffae70", True),
     "add mesh cylinder --name Coal --vertices 6 --radius 0.18 --depth 0.05 --location 0 0 0.025", "material assign Coal",
     "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces", "mode object"]
for k, (x, y, r, h) in enumerate([(0, 0, 0.09, 0.3), (0.09, 0.05, 0.07, 0.2), (-0.08, 0.04, 0.07, 0.22), (0.01, -0.09, 0.065, 0.17)]):
    L += [f"add mesh cone --name F{k} --vertices 5 --radius1 {r} --radius2 0 --depth {h} --location {x} {y} {0.04 + h / 2:.3f}",
          "material assign " + ("Tip" if k == 0 else "Flame")]
L += finish(["Coal", "F0", "F1", "F2", "F3"], "Coal", "ember")
write("ember", L, ["A cinder of the trail: a glowing coal with four little flames (the tallest the hottest; unlit), 0.36 x 0.36 x 0.34 m."])
write("wisp", [mat("Wisp", "#92e8c0", True)] + octa("Wisp", 0.15, 0.34, 0, 0, 0, "Wisp") + ["export wisp.glb"],
      ["An XP wisp: an octahedron of pale light 0.3 x 0.34 m (the largest size; small ones are scaled), unlit."])
L = [mat("Glass", "#4fa4b8"), mat("Oil", "#ffee83", True), mat("Cork", "#bd6a62"),
     "add mesh cylinder --name Jar --vertices 8 --radius 0.13 --depth 0.22 --location 0 0 0.11", "material assign Glass",
     "add mesh cylinder --name Band --vertices 8 --radius 0.137 --depth 0.09 --location 0 0 0.1", "material assign Oil",
     "add mesh cylinder --name Neck --vertices 6 --radius 0.06 --depth 0.08 --location 0 0 0.26", "material assign Glass",
     "add mesh cylinder --name Cork --vertices 6 --radius 0.07 --depth 0.06 --location 0 0 0.32", "material assign Cork"]
L += finish(["Jar", "Band", "Neck", "Cork"], "Jar", "flask")
write("flask", L, ["A lamp-oil flask (heals): a squat teal jar with a glowing band of oil and a cork, 0.27 x 0.27 x 0.35 m."])
print("wrote ground.png and", ", ".join(["ground"] + [f"decor{i}" for i in range(4)] +
      ["moths", "shambler", "hound", "brute", "boss", "mote", "ring", "spark", "ember", "wisp", "flask"]))
